@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class Institution {
  + institutionCode : int
}

class Article {
  + DOI : string
  + title : string
  + authors : Person[]
  + position : int
}

abstract class ScientificArticle {
  + citationCount : int
}

class PeerReviewedPaper extends ScientificArticle {
  + reviewer : Person
}

class TechnicalReport extends ScientificArticle {}

class Publisher {
  + name : string
}

class Journal {
  + publisher : Publisher
  + journalName : string
  + impactFactor : float
}

Person "1" -- "0..*" Institution : works_for
Person "1" *-- "0..*" Article : author
Person "1" *-- "0..*" Article : reviewer
Institution "1" -- "0..*" TechnicalReport : publishes
Publisher "1" *-- "0..*" Journal : publishes

@enduml

